//		Exec(ctx)
func (u *LLMModelUpsertBulk) Ignore() *LLMModelUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *LLMModelUpsertBulk) DoNothing() *LLMModelUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the LLMModelCreateBulk.OnConflict
// documentation for more info.
func (u *LLMModelUpsertBulk) Update(set func(*LLMModelUpsert)) *LLMModelUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&LLMModelUpsert{UpdateSet: update})
	}))
	return u
}

